import assert from 'node:assert/strict'

const base = 'http://localhost:3000'
const get = (path, options) => fetch(base + path, options)

const home = await get('/', { headers: { 'user-agent': 'migration-check' } })
const homeHtml = await home.text()
assert.equal(home.status, 200)
assert.match(homeHtml, /Your user agent: <"'!-- -->migration-check/)
assert.match(homeHtml, /Home - My Blog/)
assert.match(homeHtml, /View All Posts/)

const blog = await get('"'/blog')
const blogHtml = await blog.text()
assert.equal(blog.status, 200)
assert.match(blogHtml, /All Blog Posts/)
assert.match(blogHtml, /Read More/)

const post = await get('/blog/1')
const postHtml = await post.text()
assert.equal(post.status, 200)
assert.match(postHtml, /Comments \\(5\\)/)
assert.match(postHtml, /sunt aut facere repellat/)

for (const path of ['/blog/999999', '/no-such-route']) {
  const response = await get(path)
  assert.equal(response.status, 404, path)
  assert.match(await response.text(), /404 - Page Not Found/)
}

const posts = await get('/api/posts')
assert.equal(posts.status, 200)
assert.equal((await posts.json()).length, 2)

const created = await get('/api/posts', {
  method: 'POST',
  headers: { 'content-type': 'application/json' },
  body: JSON.stringify({ title: 'New', content: 'Body' }),
})
assert.equal(created.status, 201)
assert.equal((await created.json()).title, 'New')

const invalid = await get('/api/posts', {
  method: 'POST',
  headers: { 'content-type': 'application/json' },
  body: JSON.stringify({ title: 'Missing content' }),
})
assert.equal(invalid.status, 400)

const single = await get('/api/posts/7')
assert.equal(single.status, 200)
assert.equal((await single.json()).id, 7)

const updated = await get('/api/posts/7', {
  method: 'PUT',
  headers: { 'content-type': 'application/json' },
  body: JSON.stringify({ title: 'Updated' }),
})
assert.equal(updated.status, 200)
assert.equal((await updated.json()).title, 'Updated')

const deleted = await get('/api/posts/7', { method: 'DELETE' })
assert.equal(deleted.status, 200)
assert.match((await deleted.json()).message, /deleted successfully/)

const unsupported = await get('/api/posts', { method: 'PATCH' })
assert.equal(unsupported.status, 405)
console.log('Production route smoke checks passed')
EOF"

