/bin/bash -lc "node --input-type=module <<'EOF'
import assert from 'node:assert/strict'

const base = 'http://localhost:3000'
async function check(path, status, options) {
  const response = await fetch(base + path, options)
  assert.equal(response.status, status, "'`${path}: expected ${status}, got ${response.status}`)
  return response
}

const homeHtml = await (await check('"'/', 200, { headers: { 'user-agent': 'migration-check' } })).text()
assert.match(homeHtml, /Your user agent: <"'!-- -->migration-check/)
assert.match(homeHtml.slice(0, homeHtml.indexOf('"'</head>')), /<title>Home - My Blog<\\/title>/)
assert.match(homeHtml, /href=\"\\/blog\"["'^>]*>View All Posts/)

const blogHtml = await (await check('"'/blog', 200)).text()
assert.match(blogHtml, /All Blog Posts/)
assert.match(blogHtml, /Read More/)

const postHtml = await (await check('/blog/1', 200)).text()
assert.match(postHtml, /Comments \\(<"'!-- -->5<!-- -->'"\\)/)
assert.match(postHtml.slice(0, postHtml.indexOf('</head>')), /<meta property=\"og:title\"/)

for (const path of ['/blog/999999', '/no-such-route']) {
  const html = await (await check(path, 404)).text()
  assert.match(html, /404 - Page Not Found/)
}

const posts = await check('/api/posts', 200)
assert.equal((await posts.json()).length, 2)

const created = await check('/api/posts', 201, {
  method: 'POST', headers: { 'content-type': 'application/json' },
  body: JSON.stringify({ title: 'New', content: 'Body' }),
})
assert.equal((await created.json()).title, 'New')

await check('/api/posts', 400, {
  method: 'POST', headers: { 'content-type': 'application/json' },
  body: JSON.stringify({ title: 'Missing content' }),
})

assert.equal((await (await check('/api/posts/7', 200)).json()).id, 7)
const updated = await check('/api/posts/7', 200, {
  method: 'PUT', headers: { 'content-type': 'application/json' },
  body: JSON.stringify({ title: 'Updated' }),
})
assert.equal((await updated.json()).title, 'Updated')

const deleted = await check('/api/posts/7', 200, { method: 'DELETE' })
assert.match((await deleted.json()).message, /deleted successfully/)
await check('/api/posts', 405, { method: 'PATCH' })
await check('/api/posts/7', 405, { method: 'POST' })
console.log('Production route smoke checks passed')
EOF"

